update restaurants set description = 'Utö by Krog är en skärgårdsrestaurang i Edesnäs på Utö i Haninge kommun. Adressen är Edesnäs Gård 3, och restaurangen tar emot bordsbokningar och förfrågningar om catering. Enligt restaurangen vill den vara en mötesplats för både öbor och besökare.', updated_at = now() where slug = 'uto-bykrog' and description = 'Utö Bykrog är en sommaröppen restaurang i Edesnäs på Utö, vid vägen mellan Gruvbyn och Ålö. Adressen är Edesnäs Gård 3.';
update restaurants set name = 'Utö by Krog', updated_at = now() where slug = 'uto-bykrog' and name = 'Utö Bykrog';
update restaurants set description = 'Gruvbryggan är den mest trafikerade av Waxholmsbolagets bryggor på Utö i Haninge kommun, och här lägger båtarna på linje 21 från Årsta brygga till. Längre söderut angör båtarna också Näsudden och Spränga. Bryggan ligger i norra delen av Utö gästhamn, där också sjömacken finns.', updated_at = now() where slug = 'gruvbryggan' and description = 'Gruvbryggan är Waxholmsbolagets brygga på Utö, där båtarna på linje 21 från Årsta brygga lägger till. Bryggan ligger i norra delen av Utö gästhamn, där också sjömacken finns.';
update restaurants set description = 'Platsen ligger vid Bygatan i Gruvbyn på Utö, Haninge kommun. I Gruvbyn finns enligt Skärgårdsstiftelsen bland annat gästhamn, turistbyrå, livsmedelsbutik och bageri.', updated_at = now() where slug = 'lilla-haket-ninas-bod' and description = 'Lilla Haket & Ninas Bod är ett kafé i Gruvbyn på Utö, Haninge kommun.';
update restaurants set hidden_at = now(), hidden_reason = 'Inget namn är belagt av verksamheten eller en myndighet (faktagranskning batch 01, uto-0401, ub01-k016)', updated_at = now() where slug = 'lilla-haket-ninas-bod' and hidden_at is null;
update restaurants set description = 'Bakgården Utö ligger i Gruvbyn på Utö, Haninge kommun. I Gruvbyn finns ett bageri där det går att köpa nybakat bröd.', updated_at = now() where slug = 'bakgarden-uto' and description = 'Bakgården på Bygatan på Utö är ett bageri som säljer bröd och bakverk. Under sommaren finns också ett kafé.';
update restaurants set description = 'Utö Sjömack är sjömacken i norra delen av Utö gästhamn i Gruvbyn på Utö, Haninge kommun. Här går det att tanka båten och hyra moped.', updated_at = now() where slug = 'uto-gasthamn-sjomack' and description = 'Utö Sjömack har tankning dygnet runt och mopeduthyrning.';
update restaurants set description = 'Utö Värdshus är hotell, restaurang och konferensanläggning i Gruvbyn på Utö, Haninge kommun. Hotellrummen finns i Kvarnvillan, Stenhotellet och hotellstugorna, och för konferenser finns 14 mötesrum för grupper på 2 till 100 personer. Till värdshuset hör också Seglarbaren och Bakfickan.', updated_at = now() where slug = 'uto-vardshus' and description = 'Utö Värdshus är hotell, restaurang och konferensanläggning på Utö, med 80 rum och hotellstugor (200 bäddar) och 12 mötesrum. Till värdshuset hör också Seglarbaren och Bakfickan.';
