update restaurants set description = 'Utö Vandrarhem Skärgården är ett vandrarhem i Gruvbyn på Utö i Haninge kommun, i backen upp mot Utö Värdshus. Huset är en hotellbyggnad i trä i tre våningar, som enligt Haninge kommuns kulturmiljöinventering byggdes efter 1878, när Utö planerades som badort, och är ett av de första hotellen från den tiden. Vandrarhemmet har öppet april till oktober och har 73 bäddar, gemensamma kök för självhushåll och dusch och wc i korridoren. Husdjur är inte tillåtna, och man checkar in i värdshusets reception.', updated_at = now() where slug = 'stf-vandrarhem-uto' and description = 'Utö Vandrarhem ligger i backen upp mot Utö Värdshus, i grosshandlare Levins badhotell från förra sekelskiftet. Det har öppet april–oktober och har 73 bäddar, gemensamma kök för självhushåll och dusch och wc i korridoren. Husdjur är inte tillåtna, och man checkar in i värdshusets reception.';
update restaurants set name = 'Rånökällan', updated_at = now() where slug = 'rano-brygga' and name = 'Rånö Brygga';
update restaurants set description = 'Rånökällan är en restaurang på Rånö i Haninge kommun, med uteservering och veranda med utsikt över Ernviken. Den ligger intill livsmedelsbutiken Rånö Livs vid Ernviken, nära Waxholmsbåtens brygga, och drivs av Rånö Brygga, som också har stugbyn på ön. Restaurangen serverar mat, kylda drycker, glass och färskt bröd. Enligt restaurangen var sista dagen för säsongen lördagen den 8 augusti, och den öppnar igen i juni 2027.', updated_at = now() where slug = 'rano-brygga' and description is null;
